# hypothesis: Final and ClassVar attributes read back correctly through instances and classes, and reassigning a Final attribute is rejected by checkers while CPython still runs it.
from dataclasses import dataclass
from typing import ClassVar, Final, final, reveal_type


@final
class Limits:
    ceiling: Final[int] = 10
    registry: ClassVar[dict[str, int]] = {'a': 1}

    def __init__(self, scale: int) -> None:
        self.scale = scale


class Sub(Limits):  # expect-error
    pass


@dataclass(frozen=True)
class Point:
    x: Final[int]
    label: ClassVar[str] = 'pt'


def read_limits(lim: Limits) -> int:
    reveal_type(lim.ceiling)
    reveal_type(Limits.registry)
    return lim.ceiling * lim.scale


def bump_ceiling() -> None:
    try:
        Limits.ceiling = 11  # expect-error
    except TypeError:
        pass


p = Point(3)
reveal_type(p.x)
reveal_type(Point.label)
print(read_limits(Limits(2)), Point.label, p.x)
print(Sub(4).ceiling)
bump_ceiling()
print(Limits.ceiling)
